// #region 🔖Utilities
// [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities)
// Utilities MUST provide the utilities functionality.

// #region 🔖SharedLayoutTransition
// FLIP-based shared layout transition hook for smooth toolbar resizing.

type SharedLayoutRect = { left: number; top: number; width: number; height: number };
const sharedLayoutRectCache = new Map<string, SharedLayoutRect>();

/**
 * Applies a FLIP (First-Last-Invert-Play) animation to an element whenever
 * its bounding rect changes between React render cycles. Uses transform-based
 * animation (translate + scale) via the Web Animations API for compositor-friendly
 * performance. Respects prefers-reduced-motion.
 *
 * Specs: Measures previous rect (stored in ref), measures new rect in
 * useLayoutEffect (after DOM mutation, before paint), computes inverse
 * transform, then animates back to identity. Cancels in-flight animations
 * on re-trigger to avoid visual jumps.
 **/
function useSharedLayoutTransition(
  ref: React.RefObject<HTMLElement | null>,
  transformOrigin: string = "center center",
  sharedKey?: string,
): void {
  const prevRectRef = useRef<SharedLayoutRect | null>(null);
  const animRef = useRef<Animation | null>(null);
  const reducedMotionRef = useRef(typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) {
      prevRectRef.current = null;
      return;
    }

    if (animRef.current) {
      animRef.current.cancel();
      animRef.current = null;
    }

    const nextRect = el.getBoundingClientRect();
    const next: SharedLayoutRect = { left: nextRect.left, top: nextRect.top, width: nextRect.width, height: nextRect.height };

    const prevFromCache = sharedKey ? sharedLayoutRectCache.get(sharedKey) ?? null : null;
    const prev = prevRectRef.current ?? prevFromCache;

    prevRectRef.current = next;
    if (sharedKey) sharedLayoutRectCache.set(sharedKey, next);

    if (!prev || reducedMotionRef.current) return;
    if (next.width === 0 || next.height === 0 || prev.width === 0 || prev.height === 0) return;

    const dx = prev.left - next.left;
    const dy = prev.top - next.top;
    const sx = prev.width / next.width;
    const sy = prev.height / next.height;

    if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5 && Math.abs(sx - 1) < 0.01 && Math.abs(sy - 1) < 0.01) return;

    animRef.current = el.animate(
      [
        { transform: `translate(${dx}px, ${dy}px) scale(${sx}, ${sy})`, transformOrigin },
        { transform: "none", transformOrigin },
      ],
      { duration: 200, easing: "cubic-bezier(0.4, 0, 0.2, 1)" },
    );
  });

  useEffect(() => {
    return () => {
      animRef.current?.cancel();
    };
  }, []);
}

// #endregion 🔖SharedLayoutTransition

/**
 * getToolbarGroupIcon holds the data fields for a getToolbarGroupIcon record.
 **/
/**
// getToolbarGroupIcon holds the data fields for a getToolbarGroupIcon record.
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🛠️gettoolbargroupicon](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/d/i/getToolbarGroupIcon)
 **/
function getToolbarGroupIcon(groupId: string): ReactNode {
  if (groupId === "open") return <FolderIcon className="size-tiny" />;
  if (groupId === "selection") return <FocusIcon className="size-tiny" />;
  if (groupId === "filter") return <SearchIcon className="size-tiny" />;
  if (groupId === "create") return <LayoutIcon className="size-tiny" />;
  return null;
}

// #region 🔖Store

// [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🔖store](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store)
// Reactive stores for collaborative state management.

/**
 * Identity selector that returns the value unchanged.
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🛠️identityselector](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/d/i/identitySelector)
 **/
export function identitySelector<T>(value: T): T {
  return value;
}

/**
 * Abstract base class for Sync-backed reactive stores with caching and field subscriptions.
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🛠️store](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/d/i/Store)
 **/
export abstract class Store<TState> {
  public readonly guid: Guid;
  public readonly parent: SketchpadStore;
  protected readonly syncDoc: SyncDoc;
  public readonly syncMap: SyncMap<any>;
  protected readonly transact: Transact;
  protected cache?: TState;
  protected cacheHash?: string;
  protected status: StoreStatus = StoreStatus.IDLE;
  protected error?: Error;
  protected dirty: boolean = true;
  private internalObserverDisposer?: Disposable;
  private fieldSubscribers: Map<string, Set<() => void>> = new Map();
  private fieldObservers: Map<string, Disposable> = new Map();

  constructor(parent: SketchpadStore, syncMap: SyncMap<any>, transact: Transact) {
    this.guid = guid();
    this.parent = parent;
    this.syncDoc = ((parent as any).syncDoc as SyncDoc | undefined) ?? ((syncMap as any).doc as SyncDoc | undefined) ?? createSyncDocFactory()();
    this.syncMap = syncMap;
    this.transact = transact;
    this.initialize();
  }

  protected initialize(): void {
    try {
      this.status = StoreStatus.LOADING;
      this.buildSnapshot();
      this.status = StoreStatus.READY;
      this.setupDirtyTracking();
    } catch (error) {
      this.status = StoreStatus.ERROR;
      this.error = error instanceof Error ? error : new Error(String(error));
    }
  }

  protected setupDirtyTracking(): void {
    if (this.internalObserverDisposer) {
      this.internalObserverDisposer();
    }
    const callback = () => {
      this.dirty = true;
    };
    this.syncMap.observeDeep(callback);
    this.internalObserverDisposer = () => this.syncMap.unobserveDeep(callback);
  }

  protected abstract hash(state: TState): string;
  protected abstract buildSnapshot(): TState;

  snapshot(): TState {
    if (this.status === StoreStatus.ERROR) {
      throw this.error || new Error("Store is in error state");
    }
    if (!this.dirty && this.cache) {
      return this.cache;
    }
    const currentData = this.buildSnapshot();
    this.cache = currentData;
    this.dirty = false;
    return this.cache;
  }

  getState(): StoreState<TState> {
    return {
      status: this.status,
      data: this.status === StoreStatus.READY ? this.snapshot() : undefined,
      error: this.error,
    };
  }

  isReady(): boolean {
    return this.status === StoreStatus.READY;
  }

  isLoading(): boolean {
    return this.status === StoreStatus.LOADING;
  }

  isError(): boolean {
    return this.status === StoreStatus.ERROR;
  }

  protected handleError(error: unknown, context: string): void {
    this.status = StoreStatus.ERROR;
    this.error = error instanceof Error ? error : new Error(`${context}: ${String(error)}`);
    console.error(`[Store ${this.guid}] ${context}:`, error);
  }

  protected clearError(): void {
    this.error = undefined;
    if (this.status === StoreStatus.ERROR) {
      this.status = StoreStatus.READY;
    }
  }

  onChanged(subscribe: Subscribe): Unsubscribe {
    return createObserver(this.syncMap, subscribe);
  }

  onChangedDeep(subscribe: Subscribe): Unsubscribe {
    return createObserver(this.syncMap, subscribe, true);
  }

  onFieldChanged(key: string, subscribe: Subscribe, deep: boolean = false): Unsubscribe {
    const subscriberCallback = () => {
      subscribe(() => {});
    };

    if (!this.fieldSubscribers.has(key)) {
      this.fieldSubscribers.set(key, new Set());

      const fieldObserver = createFieldObserver(
        this.syncMap,
        key,
        (callback: () => void) => {
          const subscribers = this.fieldSubscribers.get(key);
          if (subscribers) {
            subscribers.forEach((cb) => cb());
          }
          callback();
          return () => {};
        },
        deep,
      );
      this.fieldObservers.set(key, fieldObserver);
    }

    const subscribers = this.fieldSubscribers.get(key)!;
    subscribers.add(subscriberCallback);

    return () => {
      subscribers.delete(subscriberCallback);

      if (subscribers.size === 0) {
        const observer = this.fieldObservers.get(key);
        if (observer) {
          observer();
          this.fieldObservers.delete(key);
        }
        this.fieldSubscribers.delete(key);
      }
    };
  }

  onFieldsChanged(keys: string[], subscribe: Subscribe, deep: boolean = false): Unsubscribe {
    return createFieldsObserver(this.syncMap, keys, subscribe, deep);
  }

  getFieldSnapshot(key: string): any {
    return (this.snapshot() as any)[key];
  }

  private pathSubscribers: Map<string, Set<() => void>> = new Map();
  private pathObservers: Map<string, Disposable> = new Map();

  onPathChanged(path: SyncPath, subscribe: Subscribe): Unsubscribe {
    const pathKey = JSON.stringify(path);
    const subscriberCallback = () => {
      subscribe(() => {});
    };
    if (!this.pathSubscribers.has(pathKey)) {
      this.pathSubscribers.set(pathKey, new Set());
      const pathObserver = createPathObserver(this.syncMap, path, () => {
        const subscribers = this.pathSubscribers.get(pathKey);
        if (subscribers) subscribers.forEach((cb) => cb());
        return () => {};
      });
      this.pathObservers.set(pathKey, pathObserver);
    }
    const subscribers = this.pathSubscribers.get(pathKey)!;
    subscribers.add(subscriberCallback);
    return () => {
      subscribers.delete(subscriberCallback);
      if (subscribers.size === 0) {
        const observer = this.pathObservers.get(pathKey);
        if (observer) {
          observer();
          this.pathObservers.delete(pathKey);
        }
        this.pathSubscribers.delete(pathKey);
      }
    };
  }

  getPathSnapshot(path: SyncPath): any {
    return getValueAtPath(this.syncMap, path);
  }

  // #endregion Store
}

/**
 * Abstract application store extending Store with undo/redo transaction support and command execution.
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🛠️appstore](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/d/i/AppStore)
 **/
export abstract class AppStore<TState, TDiff extends AppDiff<TSelectionDiff>, TSelectionDiff, TEdit extends AppEdit<TSelectionDiff>, TCommandContext, TCommandResult extends AppCommandResult<TDiff>> extends Store<TState> {
  protected readonly commandRegistry: Map<string, (context: TCommandContext, ...rest: any[]) => TCommandResult> = new Map();
  private lastDeletedTransactionEdit?: TEdit;

  private _cachedTransactionStack: TEdit[] | null = null;
  private _transactionStackObserverSet = false;

  constructor(parent: SketchpadStore, syncMap: SyncMap<any>, transact: Transact) {
    super(parent, syncMap, transact);
  }

  protected abstract applySelectionDiff(selectionDiff: TSelectionDiff): void;
  protected abstract inverseSelectionDiff(selection: any, diff: TSelectionDiff): TSelectionDiff;
  protected abstract getSelection(): any;

  get isTransactionActive(): boolean {
    return (this.syncMap.get("isTransactionActive") as boolean) || false;
  }

  set isTransactionActive(active: boolean) {
    this.syncMap.set("isTransactionActive", active);
  }

  get currentTransactionStack(): TEdit[] {
    const syncStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
    if (!syncStack) return [];

    if (!this._transactionStackObserverSet) {
      this._transactionStackObserverSet = true;
      syncStack.observe(() => {
        this._cachedTransactionStack = null;
      });
    }

    if (this._cachedTransactionStack !== null) {
      return this._cachedTransactionStack;
    }

    this._cachedTransactionStack = syncStack.toArray();
    return this._cachedTransactionStack;
  }

  get pastTransactionsStack(): TEdit[] {
    const syncStack = this.syncMap.get("pastTransactionsStack") as SyncArray<any>;
    return syncStack ? syncStack.toArray() : [];
  }

  get redoStack(): TEdit[] {
    const syncStack = this.syncMap.get("redoStack") as SyncArray<any>;
    return syncStack ? syncStack.toArray() : [];
  }

  canUndo(): boolean {
    if (this.isTransactionActive) return this.currentTransactionStack.length > 0;
    return this.pastTransactionsStack.length > 0;
  }

  canRedo(): boolean {
    if (this.isTransactionActive) return false;
    return this.redoStack.length > 0;
  }

  change(diff: TDiff): void {
    this.transact(() => {
      if (diff.fullscreenWindow !== undefined) {
        this.syncMap.set("fullscreenWindow", diff.fullscreenWindow);
      }
      if (diff.panelVisibility !== undefined) {
        let syncPanelVisibility = this.syncMap.get("panelVisibility") as SyncMap<boolean>;
        if (!syncPanelVisibility) {
          syncPanelVisibility = createSyncDocFactory()().createMap<boolean>();
          this.syncMap.set("panelVisibility", syncPanelVisibility);
        }
        Object.entries(diff.panelVisibility).forEach(([key, value]) => {
          if (value !== undefined) {
            syncPanelVisibility.set(key, value);
          }
        });
      }
      if (diff.selection) {
        this.applySelectionDiff(diff.selection);
      }
    });
  }

  startTransaction(): void {
    if (this.isTransactionActive) {
      this.finalizeTransaction();
    }
    this.isTransactionActive = true;
  }

  abortTransaction(): void {
    if (this.isTransactionActive) {
      this.transact(() => {
        const currentStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
        if (currentStack && currentStack.length > 0) {
          for (let i = currentStack.length - 1; i >= 0; i--) {
            const edit = currentStack.get(i);
            if (edit?.undo?.selectionDiff) {
              this.applySelectionDiff(edit.undo.selectionDiff);
            }
          }
          currentStack.delete(0, currentStack.length);
        }
        this.isTransactionActive = false;
      });
    }
  }

  finalizeTransaction(): void {
    if (this.isTransactionActive) {
      this.transact(() => {
        let redoStack = this.syncMap.get("redoStack") as SyncArray<any>;
        if (redoStack && redoStack.length > 0) {
          redoStack.delete(0, redoStack.length);
        }
        const currentStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
        let pastStack = this.syncMap.get("pastTransactionsStack") as SyncArray<any>;
        if (!pastStack) {
          pastStack = createSyncDocFactory()().createArray<any>();
          this.syncMap.set("pastTransactionsStack", pastStack);
        }
        if (currentStack && currentStack.length > 0) {
          const edits = currentStack.toArray();
          if (edits.length === 1) {
            pastStack.push([edits[0]]);
          } else if (edits.length > 1) {
            const firstEdit = edits[0];
            const lastEdit = edits[edits.length - 1];
            const mergedEdit = { do: lastEdit.do, undo: firstEdit.undo };
            pastStack.push([mergedEdit]);
          }
          currentStack.delete(0, currentStack.length);
        }
        this.isTransactionActive = false;
      });
    }
  }

  undo(): void {
    if (this.isTransactionActive) {
      const currentStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
      if (currentStack && currentStack.length > 0) {
        const edit = currentStack.get(currentStack.length - 1);
        this.lastDeletedTransactionEdit = edit;
        currentStack.delete(currentStack.length - 1, 1);
        if (edit?.undo?.selectionDiff) {
          this.applySelectionDiff(edit.undo.selectionDiff);
        }
      }
    } else {
      const pastStack = this.syncMap.get("pastTransactionsStack") as SyncArray<any>;
      let redoStack = this.syncMap.get("redoStack") as SyncArray<any>;
      if (!redoStack) {
        redoStack = createSyncDocFactory()().createArray<any>();
        this.syncMap.set("redoStack", redoStack);
      }
      if (pastStack && pastStack.length > 0) {
        const edit = pastStack.get(pastStack.length - 1);
        pastStack.delete(pastStack.length - 1, 1);
        redoStack.push([edit]);
        if (edit?.undo?.selectionDiff) {
          this.applySelectionDiff(edit.undo.selectionDiff);
        }
      }
    }
  }

  redo(): void {
    if (this.isTransactionActive) {
      let currentStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
      if (!currentStack) {
        currentStack = createSyncDocFactory()().createArray<any>();
        this.syncMap.set("currentTransactionStack", currentStack);
      }
      const lastDeletedEdit = this.lastDeletedTransactionEdit;
      if (lastDeletedEdit) {
        currentStack.push([lastDeletedEdit]);
        this.lastDeletedTransactionEdit = undefined;
        if (lastDeletedEdit.do?.selectionDiff) {
          this.applySelectionDiff(lastDeletedEdit.do.selectionDiff);
        }
      }
    } else {
      const pastStack = this.syncMap.get("pastTransactionsStack") as SyncArray<any>;
      const redoStack = this.syncMap.get("redoStack") as SyncArray<any>;
      if (redoStack && redoStack.length > 0) {
        const edit = redoStack.get(redoStack.length - 1);
        redoStack.delete(redoStack.length - 1, 1);
        if (pastStack) {
          pastStack.push([edit]);
        }
        if (edit?.do?.selectionDiff) {
          this.applySelectionDiff(edit.do.selectionDiff);
        }
      }
    }
  }

  protected recordEdit(result: TCommandResult): void {
    if (this.isTransactionActive && result.diff) {
      let redoStack = this.syncMap.get("redoStack") as SyncArray<any>;
      if (redoStack && redoStack.length > 0) {
        redoStack.delete(0, redoStack.length);
      }
      this.lastDeletedTransactionEdit = undefined;
      let currentStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
      if (!currentStack) {
        currentStack = createSyncDocFactory()().createArray<any>();
        this.syncMap.set("currentTransactionStack", currentStack);
      }
      const selection = this.getSelection();
      const inversedSelectionDiff = result.diff?.selection ? this.inverseSelectionDiff(selection, result.diff.selection) : undefined;
      const doStep: AppStep<TSelectionDiff> = { selectionDiff: result.diff?.selection };
      const undoStep: AppStep<TSelectionDiff> = { selectionDiff: inversedSelectionDiff };
      const edit = { do: doStep, undo: undoStep };
      currentStack.push([edit]);
    }
  }

  registerCommand(command: string, callback: (context: TCommandContext, ...rest: any[]) => TCommandResult): Disposable {
    this.commandRegistry.set(command, callback);
    return () => {
      this.commandRegistry.delete(command);
    };
  }

  abstract executeCommand<T>(command: string, ...rest: any[]): Promise<T>;
}

/**
 * Abstract app store that integrates kit diff operations for collaborative kit editing.
 * [👤semio📚js🗃️sketchpad💻sketchpad🔖utilities🛠️kitdiffappstore](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/d/i/KitDiffAppStore)
 **/
export abstract class KitDiffAppStore<TState, TDiff extends AppDiff<TSelectionDiff>, TSelectionDiff, TEdit extends KitDiffAppEdit<TSelectionDiff>, TCommandContext, TCommandResult extends KitDiffAppCommandResult<TDiff>> extends AppStore<
  TState,
  TDiff,
  TSelectionDiff,
  TEdit,
  TCommandContext,
  TCommandResult
> {
  constructor(parent: SketchpadStore, syncMap: SyncMap<any>, transact: Transact) {
    super(parent, syncMap, transact);
  }

  abstract kit(): KitStore;

  abortTransaction(): void {
    if (this.isTransactionActive) {
      this.transact(() => {
        const currentStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
        if (currentStack && currentStack.length > 0) {
          for (let i = currentStack.length - 1; i >= 0; i--) {
            const edit = currentStack.get(i);
            if (edit?.undo) {
              if (edit.undo.kitDiff) {
                this.kit().apply(edit.undo.kitDiff);
              }
              if (edit.undo.selectionDiff) {
                this.applySelectionDiff(edit.undo.selectionDiff);
              }
            }
          }
          currentStack.delete(0, currentStack.length);
        }
        this.isTransactionActive = false;
      });
    }
  }

  undo(): void {
    if (this.isTransactionActive) {
      const currentStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
      if (currentStack && currentStack.length > 0) {
        const edit = currentStack.get(currentStack.length - 1);
        (this as any).lastDeletedTransactionEdit = edit;
        currentStack.delete(currentStack.length - 1, 1);
        if (edit?.undo) {
          if (edit.undo.kitDiff) {
            this.kit().apply(edit.undo.kitDiff);
          }
          if (edit.undo.selectionDiff) {
            this.applySelectionDiff(edit.undo.selectionDiff);
          }
        }
      }
    } else {
      const pastStack = this.syncMap.get("pastTransactionsStack") as SyncArray<any>;
      let redoStack = this.syncMap.get("redoStack") as SyncArray<any>;
      if (!redoStack) {
        redoStack = createSyncDocFactory()().createArray<any>();
        this.syncMap.set("redoStack", redoStack);
      }
      if (pastStack && pastStack.length > 0) {
        const edit = pastStack.get(pastStack.length - 1);
        pastStack.delete(pastStack.length - 1, 1);
        redoStack.push([edit]);
        if (edit?.undo) {
          if (edit.undo.kitDiff) {
            this.kit().apply(edit.undo.kitDiff);
          }
          if (edit.undo.selectionDiff) {
            this.applySelectionDiff(edit.undo.selectionDiff);
          }
        }
      }
    }
  }

  redo(): void {
    if (this.isTransactionActive) {
      let currentStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
      if (!currentStack) {
        currentStack = createSyncDocFactory()().createArray<any>();
        this.syncMap.set("currentTransactionStack", currentStack);
      }
      const lastDeletedEdit = (this as any).lastDeletedTransactionEdit;
      if (lastDeletedEdit) {
        currentStack.push([lastDeletedEdit]);
        (this as any).lastDeletedTransactionEdit = undefined;
        if (lastDeletedEdit.do) {
          if (lastDeletedEdit.do.kitDiff) {
            this.kit().apply(lastDeletedEdit.do.kitDiff);
          }
          if (lastDeletedEdit.do.selectionDiff) {
            this.applySelectionDiff(lastDeletedEdit.do.selectionDiff);
          }
        }
      }
    } else {
      const pastStack = this.syncMap.get("pastTransactionsStack") as SyncArray<any>;
      const redoStack = this.syncMap.get("redoStack") as SyncArray<any>;
      if (redoStack && redoStack.length > 0) {
        const edit = redoStack.get(redoStack.length - 1);
        redoStack.delete(redoStack.length - 1, 1);
        if (pastStack) {
          pastStack.push([edit]);
        }
        if (edit?.do) {
          if (edit.do.kitDiff) {
            this.kit().apply(edit.do.kitDiff);
          }
          if (edit.do.selectionDiff) {
            this.applySelectionDiff(edit.do.selectionDiff);
          }
        }
      }
    }
  }

  protected recordEdit(result: TCommandResult): void {
    if (this.isTransactionActive && (result.diff || result.kitDiff)) {
      let redoStack = this.syncMap.get("redoStack") as SyncArray<any>;
      if (redoStack && redoStack.length > 0) {
        redoStack.delete(0, redoStack.length);
      }
      (this as any).lastDeletedTransactionEdit = undefined;
      let currentStack = this.syncMap.get("currentTransactionStack") as SyncArray<any>;
      if (!currentStack) {
        currentStack = createSyncDocFactory()().createArray<any>();
        this.syncMap.set("currentTransactionStack", currentStack);
      }
      const selection = this.getSelection();
      const inversedSelectionDiff = result.diff?.selection ? this.inverseSelectionDiff(selection, result.diff.selection) : undefined;
      const kitStore = this.kit();
      const kitState = kitStore.getSnapshot().kit;
      const inversedKitDiff = result.kitDiff ? inverseKitDiff(kitState, result.kitDiff) : undefined;
      const doStep: KitDiffAppStep<TSelectionDiff> = { kitDiff: result.kitDiff, selectionDiff: result.diff?.selection };
      const undoStep: KitDiffAppStep<TSelectionDiff> = { kitDiff: inversedKitDiff, selectionDiff: inversedSelectionDiff };
      const edit = { do: doStep, undo: undoStep };
      currentStack.push([edit]);
    }
  }
}

