const KIT_DIAGRAM_DEBUG = false;
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖designfamilyhelpers🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨kitdiagramdebugintervalms](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Design%20Family%20Helpers/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/KIT_DIAGRAM_DEBUG_INTERVAL_MS)
 * KIT_DIAGRAM_DEBUG_INTERVAL_MS holds the data fields for a KIT_DIAGRAM_DEBUG_INTERVAL_MS record.
 **/
const KIT_DIAGRAM_DEBUG_INTERVAL_MS = 400;

/**
 * KIT_DIAGRAM_FALLBACK_KIND holds the data fields for a KIT_DIAGRAM_FALLBACK_KIND record.
 * [👤semio📚js🗃️sketchpad💻kit🔖designfamilyhelpers🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨kitdiagramfallbackkind](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Design%20Family%20Helpers/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/KIT_DIAGRAM_FALLBACK_KIND)
 **/
const KIT_DIAGRAM_FALLBACK_KIND: KitDiagramNodeKind = "quality";
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖designfamilyhelpers🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨kitdiagramproximityconnectdistance](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Design%20Family%20Helpers/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE)
 * KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE holds the data fields for a KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE record.
 **/
const KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE = Math.max(KIT_DIAGRAM_DEFAULT_SHAPE_STRATEGY.frame.width, KIT_DIAGRAM_DEFAULT_SHAPE_STRATEGY.frame.height) * 0.55;

/** isKitDiagramNodeKind holds the data fields for a isKitDiagramNodeKind record.
 **/
// [👤semio📚js🗃️sketchpad💻kit🔖designfamilyhelpers🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨resolvediagramedgeanchors](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Design%20Family%20Helpers/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/resolveDiagramEdgeAnchors)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨iskitdiagramnodekind](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/isKitDiagramNodeKind)
 **/
const isKitDiagramNodeKind = (value: string): value is KitDiagramNodeKind => value === "type" || value === "design" || value === "quality" || value === "port" || value === "file" || value === "folder" || value === "author";

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨toreactflowposition](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/toReactFlowPosition)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨toreactflowposition](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/toReactFlowPosition)
 * toReactFlowPosition holds the data fields for a toReactFlowPosition record.
 **/
const toReactFlowPosition = (side: "top" | "right" | "bottom" | "left"): Position => {
  if (side === "top") return Position.Top;
  if (side === "right") return Position.Right;
  if (side === "bottom") return Position.Bottom;
  return Position.Left;
};

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨resolvediagramnodekind](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/resolveDiagramNodeKind)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨resolvediagramnodekind](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/resolveDiagramNodeKind)
 * resolveDiagramNodeKind holds the data fields for a resolveDiagramNodeKind record.
 **/
const resolveDiagramNodeKind = (node: any): KitDiagramNodeKind => {
  const dataKind = (node?.data as KitDiagramNode | undefined)?.kind;
  if (dataKind && isKitDiagramNodeKind(dataKind)) return dataKind;
  const idKind = typeof node?.id === "string" ? node.id.split(":", 2)[0] : "";
  if (isKitDiagramNodeKind(idKind)) return idKind;
  return KIT_DIAGRAM_FALLBACK_KIND;
};

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨resolvediagramnodeposition](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/resolveDiagramNodePosition)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨resolvediagramnodeposition](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/resolveDiagramNodePosition)
 * resolveDiagramNodePosition holds the data fields for a resolveDiagramNodePosition record.
 **/
const resolveDiagramNodePosition = (node: any): { x: number; y: number } => {
  const position = node?.internals?.positionAbsolute ?? node?.positionAbsolute ?? node?.position;
  if (position && Number.isFinite(position.x) && Number.isFinite(position.y)) return position;
  return { x: 0, y: 0 };
};

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨resolvediagramnodeframe](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/resolveDiagramNodeFrame)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨resolvediagramnodeframe](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/resolveDiagramNodeFrame)
 * resolveDiagramNodeFrame holds the data fields for a resolveDiagramNodeFrame record.
 **/
const resolveDiagramNodeFrame = (node: any, kind: KitDiagramNodeKind) => normalizeKitDiagramFrame({ width: node?.width, height: node?.height }, getKitDiagramNodeFrameForKind(kind));

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨resolvediagramedgeanchors](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/resolveDiagramEdgeAnchors)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨resolvediagramedgeanchors](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/resolveDiagramEdgeAnchors)
 * resolveDiagramEdgeAnchors holds the data fields for a resolveDiagramEdgeAnchors record.
 **/
const resolveDiagramEdgeAnchors = (sourceNode: any, targetNode: any) => {
  const sourceKind = resolveDiagramNodeKind(sourceNode);
  const targetKind = resolveDiagramNodeKind(targetNode);
  const sourcePosition = resolveDiagramNodePosition(sourceNode);
  const targetPosition = resolveDiagramNodePosition(targetNode);
  const sourceFrame = resolveDiagramNodeFrame(sourceNode, sourceKind);
  const targetFrame = resolveDiagramNodeFrame(targetNode, targetKind);
  const anchors = resolveKitDiagramAnchorPair({ kind: sourceKind, position: sourcePosition, frame: sourceFrame }, { kind: targetKind, position: targetPosition, frame: targetFrame });
  return {
    sx: anchors.source.absolutePoint.x,
    sy: anchors.source.absolutePoint.y,
    tx: anchors.target.absolutePoint.x,
    ty: anchors.target.absolutePoint.y,
    sourcePos: toReactFlowPosition(anchors.source.localPoint.side),
    targetPos: toReactFlowPosition(anchors.target.localPoint.side),
  };
};

/** FloatingEdge holds the data fields for a FloatingEdge record.
 **/
// [👤semio📚js🗃️sketchpad💻kit🔖designfamilyhelpers🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨floatingedge](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Design%20Family%20Helpers/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/FloatingEdge)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨floatingedge](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/FloatingEdge)
 **/
const FloatingEdge: FC<EdgeProps> = ({ id, source, target, markerEnd, style, selected, data }) => {
  const sourceNode = useInternalNode(source);
  const targetNode = useInternalNode(target);
  const debugLogRef = useRef(0);

  if (!sourceNode || !targetNode) {
    return null;
  }

  const { sx, sy, tx, ty, sourcePos: sPos, targetPos: tPos } = resolveDiagramEdgeAnchors(sourceNode, targetNode);

  const [edgePath] = getBezierPath({
    sourceX: sx,
    sourceY: sy,
    sourcePosition: sPos,
    targetX: tx,
    targetY: ty,
    targetPosition: tPos,
  });

  const relationship = data?.relationship as "part-of" | "reference";
  let stroke = relationship === "part-of" ? "var(--accent-secondary)" : "var(--foreground)";
  let strokeWidth = relationship === "reference" ? 1 : 3;
  let dasharray = relationship === "reference" ? "5 5" : undefined;
  let opacity = 1;

  if (selected) {
    stroke = "var(--active-base)";
    strokeWidth = Math.max(strokeWidth, 3);
    dasharray = undefined;
    opacity = 1;
  }

  return (
    <g>
      <BaseEdge
        id={id}
        path={edgePath}
        style={{
          ...style,
          stroke,
          strokeWidth,
          strokeDasharray: dasharray,
          opacity,
        }}
        className="transition-colors duration-200"
      />
      {KIT_DIAGRAM_DEBUG ? <circle cx={sx} cy={sy} r={3} fill="var(--accent-secondary)" stroke="none" pointerEvents="none" /> : null}
      {KIT_DIAGRAM_DEBUG ? <circle cx={tx} cy={ty} r={3} fill="var(--foreground)" stroke="none" pointerEvents="none" /> : null}
    </g>
  );
};

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨floatingconnectionline](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/FloatingConnectionLine)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨floatingconnectionline](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/FloatingConnectionLine)
 * FloatingConnectionLine holds the data fields for a FloatingConnectionLine record.
 **/
const FloatingConnectionLine: FC<ConnectionLineComponentProps> = ({ fromX, fromY, toX, toY, fromNode, toNode, pointer }) => {
  const { getNodes } = useReactFlow();
  const fromKind = resolveDiagramNodeKind(fromNode);
  const fromPosition = resolveDiagramNodePosition(fromNode);
  const fromFrame = resolveDiagramNodeFrame(fromNode, fromKind);
  const targetPoint = pointer ?? { x: toX, y: toY };
  const sourceDirection = kitDiagramVector(kitDiagramToAbsolutePoint(fromPosition, { x: fromFrame.width / 2, y: fromFrame.height / 2 }), targetPoint);
  const sourceAnchor = getKitDiagramShapeStrategy(fromKind).resolveNearestPoint(sourceDirection, fromFrame);
  let sourceX = kitDiagramToAbsolutePoint(fromPosition, sourceAnchor).x;
  let sourceY = kitDiagramToAbsolutePoint(fromPosition, sourceAnchor).y;
  let sourcePosition = toReactFlowPosition(sourceAnchor.side);
  let targetX = toX;
  let targetY = toY;
  let targetPosition = toNode ? Position.Top : toY >= fromY ? Position.Bottom : Position.Top;

  if (toNode) {
    const resolved = resolveDiagramEdgeAnchors(fromNode, toNode);
    sourceX = resolved.sx;
    sourceY = resolved.sy;
    sourcePosition = resolved.sourcePos;
    targetX = resolved.tx;
    targetY = resolved.ty;
    targetPosition = resolved.targetPos;
  } else {
    const proximity = getNodes()
      .filter((node) => node.id !== fromNode.id)
      .map((node) => {
        const kind = resolveDiagramNodeKind(node);
        const position = resolveDiagramNodePosition(node);
        const frame = resolveDiagramNodeFrame(node, kind);
        return resolveKitDiagramProximityAnchor(node.id, { kind, position, frame }, targetPoint);
      })
      .sort((a, b) => a.distance - b.distance)[0];

    if (proximity && proximity.distance <= KIT_DIAGRAM_PROXIMITY_CONNECT_DISTANCE) {
      targetX = proximity.anchor.absolutePoint.x;
      targetY = proximity.anchor.absolutePoint.y;
      targetPosition = toReactFlowPosition(proximity.anchor.localPoint.side);
    } else {
      targetPosition = toReactFlowPosition(kitDiagramInferSnapSide({ x: toX - fromPosition.x, y: toY - fromPosition.y }, fromFrame, fromFrame));
    }
  }
  const edgePath = getBezierPath({
    sourceX,
    sourceY,
    targetX,
    targetY,
    sourcePosition,
    targetPosition,
  })[0];

  return <BaseEdge path={edgePath} style={{ stroke: "var(--active-base)", strokeWidth: 3 }} />;
};

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨buildkitdiagramdata](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/buildKitDiagramData)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨buildkitdiagramdata](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/buildKitDiagramData)
 * buildKitDiagramData holds the data fields for a buildKitDiagramData record.
 **/
const buildKitDiagramData = (kit: Kit): { nodes: Node<KitDiagramNode>[]; edges: Edge[] } => {
  const nodes: Node<KitDiagramNode>[] = [];
  const edges: Edge[] = [];

  const kindGroups: KitDiagramNodeKind[] = ["type", "design", "quality", "port", "file", "folder", "author"];

  for (const kind of kindGroups) {
    let items: Array<{ guid: string; name: string; icon?: any; parentGuid?: string }> = [];

    switch (kind) {
      case "type":
        items = (kit.types ?? []).filter(Boolean).map((t) => ({
          guid: t.guid,
          name: t.name,
          icon: t.icon,
          parentGuid: t.parent?.guid,
        }));
        break;
      case "design":
        items = (kit.designs ?? []).filter(Boolean).map((d) => ({
          guid: d.guid,
          name: d.name,
          icon: d.icon,
          parentGuid: d.parent?.guid,
        }));
        break;
      case "quality":
        items = (kit.qualities ?? []).filter(Boolean).map((q) => ({ guid: q.guid, name: q.name, icon: q.icon }));
        break;
      case "port":
        items = (kit.ports ?? []).filter(Boolean).map((i) => ({ guid: i.guid, name: i.name, icon: i.icon }));
        break;
      case "file":
        items = (kit.files ?? []).filter(Boolean).map((f) => ({ guid: f.guid, name: f.name, icon: getFileIcon(f.name), parentGuid: f.folder?.guid }));
        break;
      case "folder":
        items = (kit.folders ?? []).filter(Boolean).map((f) => ({ guid: f.guid, name: f.name, icon: <FolderIcon className="size-tiny" />, parentGuid: f.parent?.guid }));
        break;
      case "author":
        items = (kit.authors ?? []).filter(Boolean).map((a) => ({ guid: a.guid, name: a.name, icon: <UserIcon className="size-tiny" /> }));
        break;
    }

    for (const item of items) {
      const nodeId = `${kind}:${item.guid}`;
      const frame = getKitDiagramNodeFrameForKind(kind);
      nodes.push({
        id: nodeId,
        type: "artifact",
        position: { x: 0, y: 0 },
        width: frame.width,
        height: frame.height,
        data: {
          guid: item.guid,
          name: item.name,
          kind,
          icon: item.icon,
          parentGuid: item.parentGuid,
        },
      });

      if (item.parentGuid) {
        let parentKind = kind;
        if (kind === "file") parentKind = "folder";
        edges.push({
          id: `${kind}-${item.parentGuid}-${item.guid}`,
          source: `${parentKind}:${item.parentGuid}`,
          target: nodeId,
          type: "floating",
          style: edgeStyle["part-of"],
          data: { relationship: "part-of" },
        });
      }
    }
  }

  for (const design of kit.designs ?? []) {
    for (const piece of design.pieces ?? []) {
      if (piece.type?.guid) {
        const typeGuid = piece.type.guid;
        const sourceId = `type:${typeGuid}`;
        const targetId = `design:${design.guid}`;
        const edgeId = `ref-${sourceId}-${targetId}`;
        if (!edges.some((e) => e.id === edgeId)) {
          edges.push({
            id: edgeId,
            source: sourceId,
            target: targetId,
            type: "floating",
            style: edgeStyle["reference"],
            data: { relationship: "reference" },
          });
        }
      }
      if (piece.design?.guid) {
        const nestedDesignGuid = piece.design.guid;
        const sourceId = `design:${nestedDesignGuid}`;
        const targetId = `design:${design.guid}`;
        const edgeId = `ref-${sourceId}-${targetId}`;
        if (!edges.some((e) => e.id === edgeId)) {
          edges.push({
            id: edgeId,
            source: sourceId,
            target: targetId,
            type: "floating",
            style: edgeStyle["reference"],
            data: { relationship: "reference" },
          });
        }
      }
    }
  }

  const portToTypes = new Map<string, Set<string>>();
  const typeByGuid = new Map((kit.types ?? []).map((typeRecord) => [typeRecord.guid, typeRecord]));
  const resolveTypeLineage = (typeGuid: string): string[] => {
    const lineage: string[] = [];
    const visited = new Set<string>();
    let currentGuid: string | undefined = typeGuid;
    while (currentGuid && !visited.has(currentGuid)) {
      visited.add(currentGuid);
      lineage.push(currentGuid);
      const currentType = typeByGuid.get(currentGuid);
      currentGuid = currentType?.parent?.guid;
    }
    return lineage;
  };
  for (const type of kit.types ?? []) {
    for (const connector of type.connectors ?? []) {
      const portGuid = connector.port?.guid;
      if (portGuid) {
        const sourceId = `port:${portGuid}`;
        for (const relatedTypeGuid of resolveTypeLineage(type.guid)) {
          const targetId = `type:${relatedTypeGuid}`;
          const edgeId = `ref-${sourceId}-${targetId}`;
          if (!edges.some((e) => e.id === edgeId)) {
            edges.push({
              id: edgeId,
              source: sourceId,
              target: targetId,
              type: "floating",
              style: edgeStyle["reference"],
              data: { relationship: "reference" },
            });
          }
          if (!portToTypes.has(portGuid)) portToTypes.set(portGuid, new Set());
          portToTypes.get(portGuid)!.add(relatedTypeGuid);
        }
      }
    }
  }

  const portGroups = createPortGroupMap(kit.ports ?? []);
  const groupToTypes = new Map<string, Set<string>>();
  for (const [portGuid, typeGuids] of portToTypes) {
    const groupRoot = portGroups.get(portGuid) ?? portGuid;
    if (!groupToTypes.has(groupRoot)) groupToTypes.set(groupRoot, new Set());
    for (const typeGuid of typeGuids) groupToTypes.get(groupRoot)!.add(typeGuid);
  }
  for (const typeGuids of groupToTypes.values()) {
    const arr = Array.from(typeGuids);
    for (let i = 0; i < arr.length; i++) {
      for (let j = i + 1; j < arr.length; j++) {
        const sourceId = `type:${arr[i]}`;
        const targetId = `type:${arr[j]}`;
        const edgeId = `compat-${sourceId}-${targetId}`;
        if (!edges.some((e) => e.id === edgeId)) {
          edges.push({
            id: edgeId,
            source: sourceId,
            target: targetId,
            type: "floating",
            style: edgeStyle["reference"],
            data: { relationship: "reference" },
          });
        }
      }
    }
  }

  return { nodes, edges };
};

const hasAnySelection = (selection: KitAppSelection): boolean =>
  (selection.types?.length ?? 0) > 0 ||
  (selection.designs?.length ?? 0) > 0 ||
  (selection.qualities?.length ?? 0) > 0 ||
  (selection.ports?.length ?? 0) > 0 ||
  (selection.tags?.length ?? 0) > 0 ||
  (selection.files?.length ?? 0) > 0 ||
  (selection.folders?.length ?? 0) > 0 ||
  (selection.authors?.length ?? 0) > 0;

const buildSelectionKit = (kit: Kit, selection: KitAppSelection): Kit => {
  const selectedTypeGuids = new Set(selection.types ?? []);
  const selectedDesignGuids = new Set(selection.designs ?? []);
  const selectedPortGuids = new Set(selection.ports ?? []);
  const selectedTagGuids = new Set(selection.tags ?? []);
  const selectedFileIds = new Set(selection.files ?? []);
  const selectedFolderGuids = new Set(selection.folders ?? []);
  const selectedAuthorIds = new Set(selection.authors ?? []);
  const selectedQualityIds = new Set(selection.qualities ?? []);
  const typeByGuid = new Map((kit.types ?? []).map((t) => [t.guid, t]));
  const collectAncestorTypes = (guid: string, collected: Set<string>) => {
    if (collected.has(guid)) return;
    collected.add(guid);
    const t = typeByGuid.get(guid);
    if (t?.parent?.guid) collectAncestorTypes(t.parent.guid, collected);
  };
  const allTypeGuids = new Set(selectedTypeGuids);
  for (const guid of selectedTypeGuids) collectAncestorTypes(guid, allTypeGuids);
  const designByGuid = new Map((kit.designs ?? []).map((d) => [d.guid, d]));
  const collectAncestorDesigns = (guid: string, collected: Set<string>) => {
    if (collected.has(guid)) return;
    collected.add(guid);
    const d = designByGuid.get(guid);
    if (d?.parent?.guid) collectAncestorDesigns(d.parent.guid, collected);
  };
  const allDesignGuids = new Set(selectedDesignGuids);
  for (const guid of selectedDesignGuids) collectAncestorDesigns(guid, allDesignGuids);
  for (const designGuid of allDesignGuids) {
    const d = designByGuid.get(designGuid);
    for (const piece of d?.pieces ?? []) {
      if (piece.type?.guid && typeByGuid.has(piece.type.guid)) collectAncestorTypes(piece.type.guid, allTypeGuids);
    }
  }
  for (const typeGuid of allTypeGuids) {
    const t = typeByGuid.get(typeGuid);
    for (const connector of t?.connectors ?? []) {
      if (connector.port?.guid) selectedPortGuids.add(connector.port.guid);
    }
  }
  const types = (kit.types ?? []).filter((t) => allTypeGuids.has(t.guid));
  const designs = (kit.designs ?? []).filter((d) => allDesignGuids.has(d.guid));
  const ports = (kit.ports ?? []).filter((p) => selectedPortGuids.has(p.guid));
  const tags = (kit.tags ?? []).filter((t) => selectedTagGuids.has(t.guid));
  const files = (kit.files ?? []).filter((f) => selectedFileIds.has(f.guid));
  const folders = (kit.folders ?? []).filter((f) => selectedFolderGuids.has(f.guid));
  const authors = (kit.authors ?? []).filter((a) => selectedAuthorIds.has(a.guid));
  const qualities = (kit.qualities ?? []).filter((q) => selectedQualityIds.has(q.guid));
  return {
    ...kit,
    types,
    designs,
    ports,
    tags,
    files,
    folders,
    authors,
    qualities,
  };
};

interface KitDiagramProps {}

interface ForceNode extends SimulationNodeDatum {
  id: string;
  data: KitDiagramNode;
}

/**
 * [👤semio📚js🗃️sketchpad💻kit🔖designfamilyhelpers🔖internalstatemanagement🔖canvas🔖windows🔖diagram✂️kitdiagraminner](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Design%20Family%20Helpers/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/KitDiagramInner)
 * ForceLink holds the data fields for a ForceLink record.
 **/
interface ForceLink extends SimulationLinkDatum<ForceNode> {
  id: string;
  relationship: "part-of" | "reference";
}

// [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨kitdiagraminner](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/KitDiagramInner)
/**
 * [👤semio📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖diagram🪨kitdiagraminner](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Diagram/d/i/KitDiagramInner)
 * KitDiagramInner holds the data fields for a KitDiagramInner record.
 **/
const KitDiagramInner: FC = () => {
  const kit = useKit() as Kit | undefined;
  const reactFlowWrapper = useRef<HTMLDivElement>(null);
  const kitCommands = useKitAppCommands();
  const [selection] = useKitAppSelection();
  const [setHover] = useKitAppSetHover();
  const [clearHover] = useKitAppClearHover();
  const kitScope = useKitScope();
  const kitGuid = kitScope?.guid ?? "";
  const [activeTool] = useKitAppActiveTool();
  const isHandTool = activeTool === ToolKind.HAND;
  const actor = useSketchpadActor();
  const [diagramForce] = useKitAppDiagramForce();
  const [diagramNodes, setDiagramNodes] = useState<Node<KitDiagramNode>[]>([]);
  const [diagramEdges, setDiagramEdges] = useState<Edge[]>([]);
  const diagramNodesRef = useRef<Node<KitDiagramNode>[]>([]);
  const diagramEdgesRef = useRef<Edge[]>([]);
  const simulationRef = useRef<Simulation<ForceNode, ForceLink> | null>(null);
  const draggingNodeIdRef = useRef<string | null>(null);
  const pinnedNodeIdsRef = useRef<Set<string>>(new Set());
  const isDragReheatActiveRef = useRef(false);
  const debugTickRef = useRef(0);
  const diagramForceConfig = useMemo(() => ({ ...defaultDiagramForceSettings, ...diagramForce }), [diagramForce]);

  const filterSearchSelector = useMemo(() => createKitFilterSearchSelector(kitGuid), [kitGuid]);
  const expandedRowsSelector = useMemo(() => createKitExpandedRowsSelector(kitGuid), [kitGuid]);
  const filterSearch = useSelector(actor, filterSearchSelector) ?? "";
  const expandedRowsSet = useSelector(actor, expandedRowsSelector);
  const expandedRowsArray = useMemo(() => (expandedRowsSet ? Array.from(expandedRowsSet) : []), [expandedRowsSet]);
  const expandedRowsKey = expandedRowsArray.join(",");
  const expandedRows = useMemo(() => new Set(expandedRowsArray), [expandedRowsKey]);

  const [searchParams] = useSearchParams();
  const selectedKinds = useMemo(() => new Set(searchParams.getAll("kind") as ArtifactKind[]), [searchParams]);

  const fileUrls = useFileUrls();
  const importedFilePaths = useMemo(() => {
    const paths = new Set<string>();
    fileUrls.forEach((_url, path) => {
      const normalizedPath = path.replace(/^\.?\//, "").replace(/\/+$/, "");
      if (normalizedPath) paths.add(normalizedPath);
    });
    return paths;
  }, [fileUrls]);
  const importedFolderPaths = useMemo(() => {
    const paths = new Set<string>();
    importedFilePaths.forEach((filePath) => {
      const segments = filePath.split("/").filter(Boolean);
      for (let i = 1; i < segments.length; i++) {
        paths.add(segments.slice(0, i).join("/"));
      }
    });
    return paths;
  }, [importedFilePaths]);

  const visibleGuids = useMemo(() => {
    if (!kit) return new Set<string>();
    const guids = new Set<string>();
    const searchLower = filterSearch.toLowerCase();

    const designByGuid = new Map((kit.designs ?? []).map((d) => [d.guid, d]));
    const typeByGuid = new Map((kit.types ?? []).map((t) => [t.guid, t]));
    const folderByGuid = new Map((kit.folders ?? []).map((f) => [f.guid, f]));

    const isAncestorChainExpanded = (rowId: string, parentRowId: string | undefined): boolean => {
      if (!parentRowId) return true;
      if (!expandedRows.has(parentRowId)) return false;

      const [kind, guid] = parentRowId.split("-", 2);
      if (kind === "design") {
        const parentDesign = designByGuid.get(guid);
        if (parentDesign?.parent?.guid) {
          return isAncestorChainExpanded(parentRowId, `design-${parentDesign.parent.guid}`);
        }

        if (parentDesign?.folder) {
          return isAncestorChainExpanded(parentRowId, `folder-${parentDesign.folder}`);
        }
      } else if (kind === "type") {
        const parentType = typeByGuid.get(guid);
        if (parentType?.parent?.guid) {
          return isAncestorChainExpanded(parentRowId, `type-${parentType.parent.guid}`);
        }

        if (parentType?.folder) {
          return isAncestorChainExpanded(parentRowId, `folder-${parentType.folder}`);
        }
      } else if (kind === "folder") {
        const parentFolder = folderByGuid.get(guid);
        if (parentFolder?.parent?.guid) {
          return isAncestorChainExpanded(parentRowId, `folder-${parentFolder.parent.guid}`);
        }
      }
      return true;
    };

    const isRowVisible = (rowId: string, parentRowId: string | undefined, name: string, kind: ArtifactKind): boolean => {
      if (searchLower && !name.toLowerCase().includes(searchLower)) return false;
      if (selectedKinds.size > 0 && !selectedKinds.has(kind)) return false;
      return isAncestorChainExpanded(rowId, parentRowId);
    };

    (kit.designs ?? []).filter(Boolean).forEach((d) => {
      const rowId = `design-${d.guid}`;
      let parentRowId: string | undefined;
      if (d.parent?.guid) {
        parentRowId = `design-${d.parent.guid}`;
      } else if (d.folder) {
        parentRowId = `folder-${d.folder}`;
      }
      if (isRowVisible(rowId, parentRowId, d.name, "designs")) {
        guids.add(d.guid);
      }
    });

    (kit.types ?? []).filter(Boolean).forEach((t) => {
      const rowId = `type-${t.guid}`;
      let parentRowId: string | undefined;
      if (t.parent?.guid) {
        parentRowId = `type-${t.parent.guid}`;
      } else if (t.folder) {
        parentRowId = `folder-${t.folder}`;
      }
      if (isRowVisible(rowId, parentRowId, t.name, "types")) {
        guids.add(t.guid);
      }
    });

    (kit.qualities ?? []).filter(Boolean).forEach((q) => {
      const rowId = `quality-${q.guid}`;
      const parentRowId = q.folder ? `folder-${q.folder}` : undefined;
      if (isRowVisible(rowId, parentRowId, q.name, "qualities")) {
        guids.add(q.guid);
      }
    });

    (kit.ports ?? []).filter(Boolean).forEach((i) => {
      if ((!searchLower || i.name.toLowerCase().includes(searchLower)) && (selectedKinds.size === 0 || selectedKinds.has("ports"))) {
        guids.add(i.guid);
      }
    });

    const diagramFoldersByGuid = new Map((kit.folders ?? []).map((f) => [f.guid, f]));
    const getDiagramFolderStoragePath = (folderGuid?: string): string => {
      if (!folderGuid) return "";
      const folder = diagramFoldersByGuid.get(folderGuid);
      if (!folder) return "";
      const parentPath = getDiagramFolderStoragePath(folder.parent?.guid);
      return parentPath ? `${parentPath}/${folder.name}` : folder.name;
    };

    const filteredDiagramFolders = new Set(
      (kit.folders ?? [])
        .filter(Boolean)
        .filter((folder) => importedFolderPaths.has(getDiagramFolderStoragePath(folder.guid)))
        .map((f) => f.guid),
    );
    const filteredDiagramFiles = new Set(
      (kit.files ?? [])
        .filter(Boolean)
        .filter((file) => {
          if (!file.name?.includes(".")) return false;
          if (diagramFoldersByGuid.has(file.guid)) return false;
          const parentPath = getDiagramFolderStoragePath(file.folder?.guid);
          const storagePath = parentPath ? `${parentPath}/${file.name}` : file.name;
          if (importedFolderPaths.has(storagePath)) return false;
          return importedFilePaths.has(storagePath);
        })
        .map((f) => f.guid),
    );

    (kit.files ?? []).filter(Boolean).forEach((f) => {
      if (!filteredDiagramFiles.has(f.guid)) return;
      const rowId = `file-${f.guid}`;
      const parentRowId = f.folder?.guid ? `folder-${f.folder.guid}` : undefined;
      if (isRowVisible(rowId, parentRowId, f.name, "files")) {
        guids.add(f.guid);
      }
    });

    (kit.folders ?? []).filter(Boolean).forEach((f) => {
      if (!filteredDiagramFolders.has(f.guid)) return;
      const rowId = `folder-${f.guid}`;
      const parentRowId = f.parent?.guid ? `folder-${f.parent.guid}` : undefined;
      if (isRowVisible(rowId, parentRowId, f.name, "folders")) {
        guids.add(f.guid);
      }
    });

    (kit.authors ?? []).filter(Boolean).forEach((a) => {
      if ((!searchLower || a.name.toLowerCase().includes(searchLower)) && (selectedKinds.size === 0 || selectedKinds.has("authors"))) {
        guids.add(a.guid);
      }
    });

    return guids;
  }, [kit, filterSearch, expandedRows, selectedKinds, importedFilePaths, importedFolderPaths]);

  const { nodes: baseNodes, edges: baseEdges } = useMemo(() => {
    if (!kit) return { nodes: [], edges: [] };
    const { nodes: rfNodes, edges: rfEdges } = buildKitDiagramData(kit);

    const filteredNodes = rfNodes
      .filter((n) => visibleGuids.has(n.data.guid))
      .map((node) => {
        const [kind, guid] = node.id.split(":");
        let isSelected = false;
        if (kind === "type") isSelected = selection?.types?.includes(guid) ?? false;
        else if (kind === "design") isSelected = selection?.designs?.includes(guid) ?? false;
        else if (kind === "quality") isSelected = selection?.qualities?.includes(guid) ?? false;
        else if (kind === "port") isSelected = selection?.ports?.includes(guid) ?? false;
        else if (kind === "file") isSelected = selection?.files?.includes(guid) ?? false;
        else if (kind === "folder") isSelected = selection?.folders?.includes(guid) ?? false;
        else if (kind === "author") isSelected = selection?.authors?.includes(guid) ?? false;

        return {
          ...node,
          selected: isSelected,
          style: { ...node.style, width: node.width ?? getKitDiagramNodeFrameForKind(node.data.kind).width, height: node.height ?? getKitDiagramNodeFrameForKind(node.data.kind).height },
        };
      });

    const filteredNodeIds = new Set(filteredNodes.map((n) => n.id));
    const filteredEdges = rfEdges.filter((e) => filteredNodeIds.has(e.source) && filteredNodeIds.has(e.target));

    return { nodes: filteredNodes, edges: filteredEdges };
  }, [kit, visibleGuids, selection]);
  const baseNodeIdsKey = useMemo(() => baseNodes.map((node) => node.id).join("|"), [baseNodes]);
  const baseEdgeIdsKey = useMemo(() => baseEdges.map((edge) => edge.id).join("|"), [baseEdges]);

  const commitDiagramNodes = useCallback((nextNodes: Node<KitDiagramNode>[]) => {
    diagramNodesRef.current = nextNodes;
    setDiagramNodes(nextNodes);
  }, []);

  const syncSimulationPositions = useCallback((positions: Map<string, Node["position"]>) => {
    const simulation = simulationRef.current;
    if (!simulation) return;
    for (const simNode of simulation.nodes()) {
      const pos = positions.get(simNode.id);
      if (pos) {
        simNode.x = pos.x;
        simNode.y = pos.y;
      }
    }
  }, []);

  const setPinnedPositions = useCallback((positions: Map<string, Node["position"]>) => {
    pinnedNodeIdsRef.current = new Set(positions.keys());
    const simulation = simulationRef.current;
    if (!simulation) return;
    for (const simNode of simulation.nodes()) {
      const pos = positions.get(simNode.id);
      if (pos) {
        simNode.fx = pos.x;
        simNode.fy = pos.y;
      }
    }
  }, []);

  const clearPinnedPositions = useCallback(() => {
    pinnedNodeIdsRef.current = new Set();
    const simulation = simulationRef.current;
    if (!simulation) return;
    for (const simNode of simulation.nodes()) {
      simNode.fx = null;
      simNode.fy = null;
    }
  }, []);

  const logSimulationState = useCallback((label: string, node?: Node) => {
    if (!KIT_DIAGRAM_DEBUG) return;
    const simulation = simulationRef.current;
    if (!simulation) return;
  }, []);

  const startDragReheat = useCallback(() => {
    const simulation = simulationRef.current;
    if (!simulation) return;
    if (!isDragReheatActiveRef.current) {
      isDragReheatActiveRef.current = true;
    }
    simulation.alphaTarget(0.3).restart();
  }, []);

  const stopDragReheat = useCallback(() => {
    const simulation = simulationRef.current;
    if (simulation) {
      simulation.alphaTarget(0);
    }
    isDragReheatActiveRef.current = false;
    clearPinnedPositions();
    draggingNodeIdRef.current = null;
    logSimulationState("drag-end");
  }, [clearPinnedPositions, logSimulationState]);

  const updateNodesFromSimulation = useCallback(() => {
    const simulation = simulationRef.current;
    if (!simulation) return;
    const pinnedNodeIds = pinnedNodeIdsRef.current;
    const simNodeById = new Map(simulation.nodes().map((node) => [node.id, node]));
    const nextNodes = diagramNodesRef.current.map((node) => {
      if (pinnedNodeIds.has(node.id)) {
        return node;
      }
      const simNode = simNodeById.get(node.id);
      if (!simNode) return node;
      return { ...node, position: { x: simNode.x ?? 0, y: simNode.y ?? 0 } };
    });
    commitDiagramNodes(nextNodes);
  }, [commitDiagramNodes, baseEdgeIdsKey, baseNodeIdsKey]);

  useEffect(() => {
    const previousPositions = new Map(diagramNodesRef.current.map((node) => [node.id, node.position]));
    const nextNodes = baseNodes.map((node) => {
      const previousPosition = previousPositions.get(node.id);
      return previousPosition ? { ...node, position: previousPosition } : node;
    });
    commitDiagramNodes(nextNodes);
    diagramEdgesRef.current = baseEdges;
    setDiagramEdges(baseEdges);
  }, [baseNodes, baseEdges, commitDiagramNodes]);

  useEffect(() => {
    if (diagramNodesRef.current.length === 0) {
      if (simulationRef.current) {
        simulationRef.current.alphaTarget(0);
        simulationRef.current.stop();
        simulationRef.current = null;
      }
      return;
    }
    const nodesSnapshot = diagramNodesRef.current;
    const edgesSnapshot = diagramEdgesRef.current;
    const nodesCopy: ForceNode[] = nodesSnapshot.map((node) => ({
      id: node.id,
      x: node.position.x,
      y: node.position.y,
      data: node.data,
    }));
    const linksCopy: ForceLink[] = edgesSnapshot.map((edge) => ({
      id: edge.id,
      source: edge.source,
      target: edge.target,
      relationship: (edge.data?.relationship as "part-of" | "reference") ?? "reference",
    }));
    const simulation = forceSimulation<ForceNode, ForceLink>(nodesCopy)
      .force("charge", forceManyBody().strength(diagramForceConfig.chargeStrength))
      .force(
        "link",
        forceLink<ForceNode, ForceLink>(linksCopy)
          .id((d) => d.id)
          .distance(diagramForceConfig.linkDistance),
      )
      .force("collide", forceCollide().radius(diagramForceConfig.collideRadius))
      .force("x", forceX(0).strength(diagramForceConfig.centerStrength))
      .force("y", forceY(0).strength(diagramForceConfig.centerStrength));
    simulationRef.current = simulation;
    const snapshotPositions = new Map(nodesSnapshot.map((node) => [node.id, node.position]));
    syncSimulationPositions(snapshotPositions);
    const numTicks = Math.ceil(Math.log(simulation.alphaMin()) / Math.log(1 - simulation.alphaDecay()));
    for (let i = 0; i < numTicks; i += 1) {
      simulation.tick();
    }
    updateNodesFromSimulation();
    simulation.on("tick", updateNodesFromSimulation);

    simulation.alpha(1).restart();
    return () => {
      stopDragReheat();
      simulation.alphaTarget(0);
      simulation.stop();
      simulationRef.current = null;
    };
  }, [baseEdgeIdsKey, baseNodeIdsKey, diagramForceConfig.centerStrength, diagramForceConfig.chargeStrength, diagramForceConfig.collideRadius, diagramForceConfig.linkDistance, stopDragReheat, syncSimulationPositions, updateNodesFromSimulation]);

  const handleNodesChange = useCallback(
    (changes: any[]) => {
      const updatedNodes = applyNodeChanges(changes, diagramNodesRef.current);
      const draggingNodeId = draggingNodeIdRef.current;
      if (draggingNodeId && simulationRef.current) {
        const selectedNodes = updatedNodes.filter((node) => node.selected);
        const selectedPositions = new Map(selectedNodes.map((node) => [node.id, node.position]));
        if (selectedPositions.size > 1 && selectedPositions.has(draggingNodeId)) {
          setPinnedPositions(selectedPositions);
        } else {
          const draggedNode = updatedNodes.find((node) => node.id === draggingNodeId);
          if (draggedNode) {
            setPinnedPositions(new Map([[draggedNode.id, draggedNode.position]]));
          }
        }
      }
      commitDiagramNodes(updatedNodes);
    },
    [commitDiagramNodes, setPinnedPositions],
  );

  const handleNodeDragStart = useCallback(
    (_: any, node: Node) => {
      draggingNodeIdRef.current = node.id;
      const currentPositions = new Map(diagramNodesRef.current.map((item) => [item.id, item.position]));
      currentPositions.set(node.id, node.position);
      syncSimulationPositions(currentPositions);
      const selectedNodes = diagramNodesRef.current.filter((item) => item.selected);
      const selectedPositions = new Map(selectedNodes.map((item) => [item.id, item.position]));
      if (node.selected) {
        selectedPositions.set(node.id, node.position);
      }
      if (selectedPositions.size > 1 && node.selected) {
        setPinnedPositions(selectedPositions);
      } else {
        setPinnedPositions(new Map([[node.id, node.position]]));
      }
      startDragReheat();
      logSimulationState("drag-start", node);
    },
    [logSimulationState, setPinnedPositions, startDragReheat, syncSimulationPositions],
  );

  const handleNodeDrag = useCallback(
    (_: any, node: Node) => {
      if (draggingNodeIdRef.current !== node.id) return;
      const selectedNodes = diagramNodesRef.current.filter((item) => item.selected);
      const selectedPositions = new Map(selectedNodes.map((item) => [item.id, item.position]));
      if (node.selected) {
        selectedPositions.set(node.id, node.position);
      }
      if (selectedPositions.size > 1 && node.selected) {
        setPinnedPositions(selectedPositions);
      } else {
        setPinnedPositions(new Map([[node.id, node.position]]));
      }
      startDragReheat();
      logSimulationState("drag", node);
    },
    [logSimulationState, setPinnedPositions, startDragReheat],
  );

  const handleNodeDragStop = useCallback(
    (_: any, _node: Node) => {
      stopDragReheat();
    },
    [stopDragReheat],
  );

  const handleDragEndFallback = useCallback(() => {
    if (!draggingNodeIdRef.current && !isDragReheatActiveRef.current) return;
    stopDragReheat();
  }, [stopDragReheat]);

  useEffect(() => {
    const wrapper = reactFlowWrapper.current;
    window.addEventListener("pointerup", handleDragEndFallback);
    window.addEventListener("pointercancel", handleDragEndFallback);
    window.addEventListener("blur", handleDragEndFallback);
    if (wrapper) {
      wrapper.addEventListener("pointerleave", handleDragEndFallback);
    }
    return () => {
      window.removeEventListener("pointerup", handleDragEndFallback);
      window.removeEventListener("pointercancel", handleDragEndFallback);
      window.removeEventListener("blur", handleDragEndFallback);
      if (wrapper) {
        wrapper.removeEventListener("pointerleave", handleDragEndFallback);
      }
    };
  }, [handleDragEndFallback]);

  const onSelectionChange = useCallback(
    ({ nodes: selectedNodes }: any) => {
      const newSelection: KitAppSelection = {};
      selectedNodes.forEach((node: any) => {
        const [kind, guid] = node.id.split(":");
        if (kind === "type") {
          if (!newSelection.types) newSelection.types = [];
          newSelection.types.push(guid);
        } else if (kind === "design") {
          if (!newSelection.designs) newSelection.designs = [];
          newSelection.designs.push(guid);
        } else if (kind === "quality") {
          if (!newSelection.qualities) newSelection.qualities = [];
          newSelection.qualities.push(guid);
        } else if (kind === "port") {
          if (!newSelection.ports) newSelection.ports = [];
          newSelection.ports.push(guid);
        } else if (kind === "file") {
          if (!newSelection.files) newSelection.files = [];
          newSelection.files.push(guid);
        } else if (kind === "folder") {
          if (!newSelection.folders) newSelection.folders = [];
          newSelection.folders.push(guid);
        } else if (kind === "author") {
          if (!newSelection.authors) newSelection.authors = [];
          newSelection.authors.push(guid);
        }
      });

      actor.send({ type: "KIT.SET_SELECTION", kitGuid, selection: newSelection });
    },
    [actor, kitGuid],
  );

  const handlePaneClick = useCallback(() => {
    kitCommands.deselectAll?.();
  }, [kitCommands]);

  const handleNodeMouseEnter = useCallback(
    (_: any, node: any) => {
      const data = node.data as KitDiagramNode;
      const kind = data?.kind;
      const guid = data?.guid;
      if (!kind || !guid) return;
      if (!setHover) return;
      if (kind === "type") setHover({ type: guid });
      else if (kind === "design") setHover({ design: guid });
      else if (kind === "quality") setHover({ quality: guid });
      else if (kind === "port") setHover({ port: guid });
      else if (kind === "file") setHover({ file: guid });
      else if (kind === "folder") setHover({ folder: guid });
      else if (kind === "author") setHover({ author: guid });
    },
    [setHover],
  );

  const handleNodeMouseLeave = useCallback(() => {
    if (clearHover) clearHover();
  }, [clearHover]);

  const sketchpadCommands = useSketchpadCommands();

  useEffect(() => {
    const handleCopyKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "c" || !(e.metaKey || e.ctrlKey)) return;
      const target = e.target as HTMLElement | null;
      if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable)) return;
      if (!reactFlowWrapper.current?.contains(target)) return;
      e.preventDefault();
      if (!kit) return;
      const payload = selection && hasAnySelection(selection) ? buildSelectionKit(kit, selection) : kit;
      sketchpadCommands.copyJsonToClipboard("semio.sketchpad.app.kit.diagram.copy", payload);
    };
    window.addEventListener("keydown", handleCopyKeyDown);
    return () => window.removeEventListener("keydown", handleCopyKeyDown);
  }, [kit, selection, sketchpadCommands]);

  if (!kit) return null;

  return (
    <div ref={reactFlowWrapper} className="w-full h-full" data-testid="kit-diagram" tabIndex={0} onPointerDown={() => reactFlowWrapper.current?.focus()}>
      <Diagram
        nodes={diagramNodes}
        edges={diagramEdges}
        nodeTypes={kitNodeTypes}
        edgeTypes={{ floating: FloatingEdge }}
        connectionLineComponent={FloatingConnectionLine}
        forceConfig={{ enabled: false }}
        elementsSelectable={true}
        nodesFocusable={true}
        edgesFocusable={true}
        onSelectionChange={onSelectionChange}
        onNodesChangeReactFlow={handleNodesChange}
        onNodeMouseEnter={handleNodeMouseEnter}
        onNodeMouseLeave={handleNodeMouseLeave}
        onNodeDragStart={handleNodeDragStart}
        onNodeDrag={handleNodeDrag}
        onNodeDragStop={handleNodeDragStop}
        onPaneClick={handlePaneClick}
        selectionMode={SelectionMode.Partial}
        panOnScroll={false}
        panOnDrag={isHandTool ? true : [1, 2]}
        selectionOnDrag={!isHandTool}
        nodesDraggable={!isHandTool}
        proOptions={{ hideAttribution: true }}
      />
    </div>
  );
};

