const HoverPiecesStoreContext = createContext<HoverPiecesStore | null>(null);
const noopSubscribe = (_cb: () => void) => () => {};

// [👤semio📚js🗃️sketchpad💻design🔖store🛠️computehoverdata](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Store/d/i/computeHoverData)
/**
 * [👤semio📚js🗃️sketchpad💻design🔖store🪨computehoverdata](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Store/d/i/computeHoverData)
 * computeHoverData holds the data fields for a computeHoverData record.
 **/
function computeHoverData(store: DesignStore | null, state: DesignAppState): HoverPiecesContextValue {
  const hover = state.hover;
  const transitivelyHoveredPieces = new Set<string>();
  const transitivelyHoveredTypes = new Set<string>();

  if (!hover) return { transitivelyHoveredPieces, transitivelyHoveredTypes };

  hover.pieces?.forEach((pieceId) => transitivelyHoveredPieces.add(pieceId));

  hover.types?.forEach((typeId) => transitivelyHoveredTypes.add(typeId));

  if (store && (hover.types?.length || hover.designs?.length)) {
    const hoveredTypesSet = hover.types?.length ? new Set(hover.types) : null;
    const hoveredDesignsSet = hover.designs?.length ? new Set(hover.designs) : null;
    const design = store.design().snapshot();
    design?.pieces?.forEach((piece) => {
      if (piece.type && hoveredTypesSet?.has(piece.type.guid)) {
        transitivelyHoveredPieces.add(piece.guid);
      }
      if (piece.design && hoveredDesignsSet?.has(piece.design.guid)) {
        transitivelyHoveredPieces.add(piece.guid);
      }
    });
  }

  if (store && hover.pieces?.length) {
    const design = store.design().snapshot();
    if (design?.pieces) {
      const pieceMap = new Map<string, (typeof design.pieces)[number]>();
      for (const p of design.pieces) pieceMap.set(p.guid, p);
      for (const pieceId of hover.pieces) {
        const piece = pieceMap.get(pieceId);
        if (piece?.type?.guid) {
          transitivelyHoveredTypes.add(piece.type.guid);
        }
      }
    }
  }

  return { transitivelyHoveredPieces, transitivelyHoveredTypes };
}

/**
 * [👤semio📚js🗃️sketchpad💻design🔖imports🔖store🛠️hoverpiecesproviderinner](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Imports/s/Store/d/i/HoverPiecesProviderInner)
 * areHoverContextsEqual holds the data fields for a areHoverContextsEqual record.
 **/
function areHoverContextsEqual(a: HoverPiecesContextValue, b: HoverPiecesContextValue): boolean {
  return areSetsEqual(a.transitivelyHoveredPieces, b.transitivelyHoveredPieces) && areSetsEqual(a.transitivelyHoveredTypes, b.transitivelyHoveredTypes);
}

// [👤semio📚js🗃️sketchpad💻design🔖store🛠️hoverpiecesproviderinner](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Store/d/i/HoverPiecesProviderInner)
/**
 * [👤semio📚js🗃️sketchpad💻design🔖store🪨hoverpiecesproviderinner](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Store/d/i/HoverPiecesProviderInner)
 * HoverPiecesProviderInner holds the data fields for a HoverPiecesProviderInner record.
 **/
function HoverPiecesProviderInner({ store, children }: { store: DesignStore; children: ReactNode }) {
  const hoverStoreRef = useRef<HoverPiecesStore | null>(null);
  if (!hoverStoreRef.current) hoverStoreRef.current = new HoverPiecesStore();
  const hoverStore = hoverStoreRef.current;
  const actor = useSketchpadActorSafe();
  const kitScope = useKitScope();
  const designScope = useDesignScope();
  const syncKeyRef = useRef("");
  syncKeyRef.current = `${kitScope?.guid ?? ""}:${designScope?.guid ?? ""}`;
  const lastActorHoverRef = useRef<DesignAppHover | undefined>(undefined);

  useEffect(() => {
    const computeAndUpdate = (hover: DesignAppHover | undefined) => {
      const result = computeHoverData(store, { hover } as DesignAppState);
      hoverStore.update(result);
    };
    const getActorHover = (): DesignAppHover | undefined => {
      if (!actor) return undefined;
      return actor.getSnapshot().context.designApps[syncKeyRef.current]?.hover;
    };
    const sync = () => {
      const actorHover = getActorHover();
      const storeHover = store.snapshot().hover;
      const hover = actorHover ?? storeHover;
      lastActorHoverRef.current = hover;
      computeAndUpdate(hover);
    };
    const syncFromActor = () => {
      const actorHover = getActorHover();
      if (areHoverStatesEqual(lastActorHoverRef.current, actorHover)) return;
      lastActorHoverRef.current = actorHover;
      computeAndUpdate(actorHover);
    };
    sync();
    const unsubStore = store.subscribe(sync);
    const actorSub = actor?.subscribe(syncFromActor);
    return () => {
      unsubStore();
      actorSub?.unsubscribe();
    };
  }, [store, hoverStore, actor]);

  return <HoverPiecesStoreContext.Provider value={hoverStore}>{children}</HoverPiecesStoreContext.Provider>;
}

