// Window components MUST wrap diagram and scene views with hover and transaction providers.

/** Props interface for the Design app root component.
 * [👤semio📚js🗃️sketchpad💻design🔖imports🔖panels🔖windows🛠️appprops](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Imports/s/Panels/s/Windows/d/i/AppProps)
 **/
export interface AppProps {}

/**
 * [👤semio📚js🗃️sketchpad💻design🔖imports🔖panels🔖windows🪨diagramwindow](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Imports/s/Panels/s/Windows/d/i/DesignDiagramWindow)
 * DesignDiagramWindow holds the data fields for a DesignDiagramWindow record.
 **/
const DesignDiagramWindow = memo<{ reactFlowInstanceRef: React.RefObject<ReactFlowInstance | null> }>(({ reactFlowInstanceRef }) => {
  return (
    <HoverIntentProvider>
      <TransactionPiecesProvider>
        <HoverPiecesProvider>
          <DesignDiagram reactFlowInstanceRef={reactFlowInstanceRef} />
        </HoverPiecesProvider>
      </TransactionPiecesProvider>
    </HoverIntentProvider>
  );
});
DesignDiagramWindow.displayName = "DesignDiagramWindow";

/**
 * [👤semio📚js🗃️sketchpad💻design🔖imports🔖panels🔖windows🪨scenewindow](repo://p/u/semio/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Imports/s/Panels/s/Windows/d/i/SceneWindow)
 * SceneWindow holds the data fields for a SceneWindow record.
 **/
const SceneWindow = memo(() => {
  return (
    <HoverIntentProvider>
      <TransactionPiecesProvider>
        <HoverPiecesProvider>
          <DesignAppScene />
        </HoverPiecesProvider>
      </TransactionPiecesProvider>
    </HoverIntentProvider>
  );
});
SceneWindow.displayName = "SceneWindow";

