// [👤semio📚js🗃️sketchpad💻docs🔖panels](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Panels)
// Panel components MUST render sidebar content for the docs app.

/** Workbench holds the data fields for a Workbench record.
 **/
// [👤semio📚js🗃️sketchpad💻docs🔖panels🪨workbench](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Panels/d/i/Workbench)
/**
 * [👤semio📚js🗃️sketchpad💻docs🔖panels🪨workbench](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Panels/d/i/Workbench)
 **/
const Workbench: FC = () => {
  const navigate = useNavigate();
  useDocsMetadataVersion();
  const sections = docsRegistry.getAllSections();
  return (
    <TreeStateProvider>
      <div className="flex flex-col gap-single">
        {sections.map((section) => (
          <TreeItem key={section.id} label={section.label} icon={section.icon ? <span className="text-sm">{section.icon}</span> : undefined} onClick={() => navigate(`/docs/${section.id}`)} />
        ))}
      </div>
    </TreeStateProvider>
  );
};

// [👤semio📚js🗃️sketchpad💻docs🔖panels🪨overview](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Panels/d/i/Overview)
/**
 * [👤semio📚js🗃️sketchpad💻docs🔖panels🪨overview](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Panels/d/i/Overview)
 * Overview holds the data fields for a Overview record.
 **/
const Overview: FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  useDocsMetadataVersion();
  const pathParts = location.pathname.replace(/^\//, "").split("/").filter(Boolean);
  const section = pathParts[1] ?? "index";
  const pages = section === "index" ? docsRegistry.getAllPages() : docsRegistry.getPagesBySection(section);
  return (
    <TreeStateProvider>
      <div className="flex flex-col gap-single">
        {pages.map((page) => (
          <TreeItem key={page.path} label={page.title} icon={page.icon ? <span className="text-sm">{page.icon}</span> : undefined} onClick={() => navigate(`/${page.path}`)} />
        ))}
      </div>
    </TreeStateProvider>
  );
};

// [👤semio📚js🗃️sketchpad💻docs🔖panels🪨details](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Panels/d/i/Details)
/**
 * [👤semio📚js🗃️sketchpad💻docs🔖panels🪨details](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Panels/d/i/Details)
 * Details holds the data fields for a Details record.
 **/
const Details: FC = () => {
  const { headings } = useHeadings();
  const handleClick = useCallback((id: string) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  }, []);

  return (
    <div className="flex flex-col gap-single">
      {headings.map((h) => (
        <button key={h.id} className="text-left text-sm px-single py-tiny hover:bg-hover-panel" onClick={() => handleClick(h.id)} style={{ paddingLeft: `${Math.max(0, (h.level - 1) * 12)}px` }}>
          {h.text}
        </button>
      ))}
    </div>
  );
};

// [👤semio📚js🗃️sketchpad💻docs🔖panels🪨settings](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Panels/d/i/Settings)
/**
 * [👤semio📚js🗃️sketchpad💻docs🔖panels🪨settings](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Panels/d/i/Settings)
 * Settings holds the data fields for a Settings record.
 **/
const Settings: FC = () => {
  const [theme, setTheme, canSetTheme] = useTheme();
  const [language, setLanguage, canSetLanguage] = useLanguage();
  const [device, setDevice, canSetDevice] = useDevice();
  const [expertise, setExpertise, canSetExpertise] = useExpertise();
  const [mode, setMode, canSetMode] = useMode();
  const languageEnLabel = useLabel("semio.sketchpad.settings.language.en");
  const languageDeLabel = useLabel("semio.sketchpad.settings.language.de");
  const languagePlaceholder = useLabel("semio.sketchpad.app.home.settings.language.placeholder");
  return (
    <>
      <TreeRow>
        <ToggleGroup
          id="semio.sketchpad.app.docs.settings.theme"
          value={theme}
          onValueChange={(value: string) => setTheme?.(value as Theme)}
          showLabel
          kind="single"
          disabled={!canSetTheme}
          items={[
            { value: Theme.SYSTEM, id: "semio.sketchpad.settings.theme.system", icon: <MonitorIcon className="size-small" /> },
            { value: Theme.LIGHT, id: "semio.sketchpad.settings.theme.light", icon: <SunIcon className="size-small" /> },
            { value: Theme.DARK, id: "semio.sketchpad.settings.theme.dark", icon: <MoonIcon className="size-small" /> },
          ]}
        />
      </TreeRow>
      <TreeRow>
        <Select id="semio.sketchpad.app.docs.settings.language" value={language || "en"} onValueChange={(value: string) => setLanguage?.(value)} showLabel disabled={!canSetLanguage}>
          <SelectTrigger>
            <SelectValue placeholder={languagePlaceholder} />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="en">{languageEnLabel}</SelectItem>
            <SelectItem value="de">{languageDeLabel}</SelectItem>
          </SelectContent>
        </Select>
      </TreeRow>
      <TreeRow>
        <ToggleGroup
          id="semio.sketchpad.app.docs.settings.device"
          value={typeof device === "object" ? "desktop" : device}
          onValueChange={(value: string) => setDevice?.(value as "desktop" | "tablet")}
          showLabel
          kind="single"
          disabled={!canSetDevice}
          items={[
            { value: "desktop", id: "semio.sketchpad.settings.device.desktop", icon: <MousePointerIcon className="size-small" /> },
            { value: "tablet", id: "semio.sketchpad.settings.device.tablet", icon: <HandIcon className="size-small" /> },
          ]}
        />
      </TreeRow>
      <TreeRow>
        <ToggleGroup
          id="semio.sketchpad.app.docs.settings.expertise"
          value={expertise}
          onValueChange={(value: string) => setExpertise?.(value as Expertise)}
          showLabel
          kind="single"
          disabled={!canSetExpertise}
          items={[
            { value: Expertise.BEGINNER, id: "semio.sketchpad.settings.expertise.beginner", icon: <TutorialIcon className="size-small" /> },
            { value: Expertise.NORMAL, id: "semio.sketchpad.settings.expertise.normal", icon: <UserIcon className="size-small" /> },
            { value: Expertise.EXPERT, id: "semio.sketchpad.settings.expertise.expert", icon: <AwardIcon className="size-small" /> },
          ]}
        />
      </TreeRow>
      <TreeRow>
        <ToggleGroup
          id="semio.sketchpad.app.docs.settings.mode"
          value={mode}
          onValueChange={(value: string) => setMode?.(value as Mode)}
          showLabel
          kind="single"
          disabled={!canSetMode}
          items={[
            { value: Mode.USER, id: "semio.sketchpad.settings.mode.user", icon: <UserIcon className="size-small" /> },
            { value: Mode.DEV, id: "semio.sketchpad.settings.mode.dev", icon: <CodeIcon className="size-small" /> },
          ]}
        />
      </TreeRow>
    </>
  );
};

// #region App

// [👤semio📚js🗃️sketchpad💻docstsx🔖app](semiorepo://section/SEMIO/JS/SKETCHPAD/DOCS.TSX/APP)
// Docs app root component MUST compose MDX routing, panel sections, and layout.

/**
 * Window kind identifiers for docs app layout.
 * [👤semio📚js🗃️sketchpad💻docs🔖app🛠️app](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/App/d/i/App)
 **/
export enum DocsAppWindowKind {
  Page = "page",
}

// [👤semio📚js🗃️sketchpad💻docs🔖app🪨app](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/App/d/i/App)
/**
 * [👤semio📚js🗃️sketchpad💻docs🔖app🪨app](semiorepo://p/u/semio/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/App/d/i/App)
 * App holds the data fields for a App record.
 **/
const DocsApp: FC = () => {
  const { "*": routePath } = useParams();
  const location = useLocation();
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const addSidePanelTab = useAddSidePanelTab();
  const removeSection = useRemovePanelSection();
  const removeSidePanelTab = useRemoveSidePanelTab();
  useFocus();
  const settings = useSettings();
  const sketchpadCommands = useSketchpadCommands();
  const [mdxModule, setMdxModule] = useState<MDXModule | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const docsPath = useMemo(() => {
    const raw = (routePath ?? "").trim();
    if (raw) return raw;
    const fromLocation = location.pathname.replace(/^\//, "").replace(/^docs\/?/, "");
    return fromLocation.trim() || "index";
  }, [routePath, location.pathname]);

  useEffect(() => {
    if (appType !== "docs") return;
    return () => {};
  }, [appType, addSidePanelTab, removeSidePanelTab]);

  const defaultLayout = useMemo(
    () => ({
      root: {
        type: "row",
        content: [
          {
            type: "stack",
            size: "100%",
            content: [
              {
                type: "component",
                componentName: DocsAppWindowKind.Page,
                title: "page",
                componentState: {},
              },
            ],
          },
        ],
      },
    }),
    [],
  );
  const storedWindowLayout = useMemo(() => parseWindowLayout(settings?.apps?.docs?.windowLayout), [settings]);
  const windowLayout = useMemo(() => {
    if (!storedWindowLayout) return defaultLayout;
    const removeWorkbenchWindowFromLayout = (layoutNode: any): any => {
      if (!layoutNode || typeof layoutNode !== "object") return layoutNode;
      if (layoutNode.type === "component" && (layoutNode.componentName === "workbench" || layoutNode.componentName === "settings" || layoutNode.componentName === "chat")) {
        return null;
      }
      if (layoutNode.root && typeof layoutNode.root === "object") {
        const root = removeWorkbenchWindowFromLayout(layoutNode.root);
        if (!root) return undefined;
        return { ...layoutNode, root };
      }
      if (Array.isArray(layoutNode.content)) {
        const content = layoutNode.content.map((item: any) => removeWorkbenchWindowFromLayout(item)).filter(Boolean);
        if (content.length === 0 && (layoutNode.type === "stack" || layoutNode.type === "row" || layoutNode.type === "column")) return null;
        return { ...layoutNode, content };
      }
      if (Array.isArray(layoutNode.contentItems)) {
        const contentItems = layoutNode.contentItems.map((item: any) => removeWorkbenchWindowFromLayout(item)).filter(Boolean);
        if (contentItems.length === 0 && (layoutNode.type === "stack" || layoutNode.type === "row" || layoutNode.type === "column")) return null;
        return { ...layoutNode, contentItems };
      }
      return layoutNode;
    };
    return removeWorkbenchWindowFromLayout(storedWindowLayout) || defaultLayout;
  }, [storedWindowLayout, defaultLayout]);
  const lastLayoutRef = useRef<any>(null);

  useEffect(() => {
    if (appType !== "docs") return;
    addSection("workbench", {
      id: "semio.sketchpad.app.docs.docs",
      specificity: 20,
      order: 1,
      content: () => <Workbench />,
    });
    addSection("workbench", {
      id: "semio.sketchpad.app.docs.overview",
      specificity: 20,
      order: 2,
      content: () => <Overview />,
    });
    addSection("details", {
      id: "semio.sketchpad.app.docs.page",
      specificity: 20,
      order: 1,
      content: () => <Details />,
    });

    addSection("toolbar", {
      id: "semio.sketchpad.app.docs.toolbar.empty",
      specificity: 20,
      order: 0,
      toolbarPlaceholder: true,
      content: () => null,
    });

    return () => {
      removeSection("workbench", "semio.sketchpad.app.docs.docs");
      removeSection("workbench", "semio.sketchpad.app.docs.overview");
      removeSection("details", "semio.sketchpad.app.docs.page");
      removeSection("toolbar", "semio.sketchpad.app.docs.toolbar.empty");
    };
  }, [appType, addSection, removeSection]);

  useEffect(() => {
    if (appType !== "docs") {
      setLoading(false);
      return;
    }

    const loadContent = async () => {
      setLoading(true);
      setError(null);
      try {
        const module = await loadMDXFile(docsPath);
        if (module) {
          setMdxModule(module);
        } else {
          setError(`Failed to load ${docsPath}`);
        }
      } catch (err) {
        setError((err as Error).message);
      } finally {
        setLoading(false);
      }
    };

    loadContent();
  }, [docsPath, appType]);

  const windowConfig: AppWindowConfig = useMemo(
    () => ({
      windowKinds: [
        {
          id: DocsAppWindowKind.Page,
          label: "page",
          component: () => {
            if (loading) return <PageCanvas frontmatter={{ title: "Loading...", description: "" }} />;
            if (error || !mdxModule) return <PageCanvas frontmatter={{ title: "Error", description: error || "Content not found" }} />;
            return <PageCanvas MDXContent={mdxModule.default} frontmatter={mdxModule.frontmatter} />;
          },
        },
      ],
      defaultLayout,
    }),
    [defaultLayout, error, loading, mdxModule],
  );

  const handleLayoutChange = useCallback(
    (layout: any) => {
      const next = stringifyWindowLayout(layout);
      if (!next) return;
      const prev = stringifyWindowLayout(lastLayoutRef.current);
      if (next === prev) return;
      lastLayoutRef.current = layout;
      sketchpadCommands.setState("semio.sketchpad.app.docs.windowLayout", {
        settings: {
          apps: {
            docs: {
              windowLayout: next,
            },
          },
        },
      });
    },
    [sketchpadCommands],
  );

  return (
    <HeadingsProvider>
      <Canvas>
        <LayoutCanvas windowConfig={windowConfig} layoutState={windowLayout} onLayoutChange={handleLayoutChange} />
      </Canvas>
    </HeadingsProvider>
  );
};

// #endregion DocsApp

