import type { BlobAssetStore, KitStoreStatus, KitSyncState, ObservablePathStore, UndoableKitStore } from "@semio/js";
import type { KitJsonFileAdapter } from "../studio/studio";
import { createIndexeddbPersistenceFactory, createJsonFileKitStore, JsonFileKitStore } from "../studio/studio";
import "./globals.css";

export { createJsonFileKitStore, JsonFileKitStore };
export type { BlobAssetStore, KitJsonFileAdapter, KitStoreSnapshot, KitStoreStatus, KitSyncState, ObservablePathStore, UndoableKitStore };

appRegistry.register(designConfig);
appRegistry.register(docsConfig);
appRegistry.register(feedbackConfig);
appRegistry.register(homeConfig);
appRegistry.register(kitConfig);
appRegistry.register(qualityConfig);
appRegistry.register(typeConfig);

// #region 🔖VscodeAdapter
// VS Code webview adapter for JsonFileKitStore. Bridges file I/O via postMessage.
const isVscodeWebview = typeof globalThis !== "undefined" && typeof (globalThis as any).window !== "undefined" && typeof (globalThis as any).window.__SEMIO_VSCODE_API__ !== "undefined";

function createVscodeAdapter(): KitJsonFileAdapter {
  const vscodeApi = (window as any).__SEMIO_VSCODE_API__;
  return {
    read: async () => (window as any).__SEMIO_KIT_JSON__ ?? null,
    write: async (json: string) => {
      vscodeApi.postMessage({ kind: "kit.save", content: json });
    },
  };
}

function createVscodeFileKitStoreFactory(): SketchpadKitStoreFactory {
  const vscodeApi = (window as any).__SEMIO_VSCODE_API__;
  return async (kit) => {
    const adapter: KitJsonFileAdapter = {
      read: async () => JSON.stringify(kit),
      write: async (json: string) => {
        vscodeApi.postMessage({ kind: "kit.save", content: json });
      },
    };
    return createJsonFileKitStore(adapter);
  };
}
// #endregion 🔖VscodeAdapter

const temporaryKitStoreFactory: SketchpadKitStoreFactory = (kit) => new InMemoryKitStore(kit);

async function boot() {
  let kitStore = undefined;
  let fileKitStoreFactory: SketchpadKitStoreFactory | undefined = undefined;
  if (isVscodeWebview) {
    const adapter = createVscodeAdapter();
    kitStore = await createJsonFileKitStore(adapter);
    fileKitStoreFactory = createVscodeFileKitStoreFactory();
    // Listen for external updates from the VS Code extension host.
    (window as any).__SEMIO_ON_EXTERNAL_UPDATE__ = (json: string) => {
      try {
        const parsed = JSON.parse(json);
        const { KitSchema } = require("@semio/js");
        const kit = KitSchema.parse(parsed);
        kitStore!.applyExternalUpdate(kit);
      } catch {
        /* ignore parse errors */
      }
    };
    // Auto-save is handled centrally by SketchpadStore.registerKitStore.
  }

  const indexeddbPersistenceFactory = isVscodeWebview ? undefined : createIndexeddbPersistenceFactory();

  const rootElement = document.getElementById("root");
  if (!rootElement) {
    throw new Error('Sketchpad root element "#root" was not found.');
  }

  getOrCreateDomRoot(rootElement).render(
    <div className="h-screen w-screen">
      <Sketchpad persistenceFactory={indexeddbPersistenceFactory} kitStore={kitStore} temporaryKitStoreFactory={isVscodeWebview ? undefined : temporaryKitStoreFactory} fileKitStoreFactory={fileKitStoreFactory} />
    </div>,
  );
}

// Auto-boot only in standalone mode. In VS Code webview, webview.tsx handles its own boot.
// The extension host injects __SEMIO_VSCODE_API__ in the head before module scripts run.
if (typeof document !== "undefined" && document.getElementById("root") && !isVscodeWebview) {
  boot();
}
